// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import {
    createUser,
    getCsrf,
    createCredentials,
    createSignout,
    createCollection,
    createLink,
    createHighlight,
    getHighlightsList,
    updateHighlight,
    deleteHighlight,
    deleteLink,
    deleteCollection
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    // The second user. Its username is made unique per run so the test can be re-run.
    const ownerUsername = uniqueSuffix("tb-hl-owner");
    const ownerPassword = "testbotpassword123";

    const usersPostResponse = await createUser(client, ownerUsername, ownerPassword, "Testbot Highlight Owner", 201);
    expect(usersPostResponse.statusCode, 'registration returns 201 Created').toBe(201);
    expect(getResponseValue(usersPostResponse, "response.username"), 'the second user was registered under the run-unique name').toBe(ownerUsername);
    expect(getResponseValue(usersPostResponse, "response.id"), 'second user id').toBeGreaterThan(0);

    const csrfGetResponse = await getCsrf(client);
    expect(csrfGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(csrfGetResponse, "csrfToken"), 'csrf token').toMatch(/^[0-9a-f]{16,}$/i);

    // Signing the second user in sets a session cookie, which next-auth's getToken()
    // reads in preference to the bearer token, so the steps below act as that user.
    const credentialsPostResponse = await createCredentials(
        client,
        getResponseValue(usersPostResponse, "response.username"),
        ownerPassword,
        getResponseValue(csrfGetResponse, "csrfToken")
    );
    expect(credentialsPostResponse.statusCode, 'status code').toBe(302);

    const collectionsPostResponse = await createCollection(client, "Testbot Owner Collection", "#ef4444");
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Testbot Owner Collection");
    expect(getResponseValue(collectionsPostResponse, "response.ownerId"), 'the collection belongs to the second user').toBe(getResponseValue(usersPostResponse, "response.id"));

    const linksPostResponse = await createLink(
        client,
        "Testbot Owner Source",
        "https://example.com/testbot-owner",
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.url"), 'link url').toBe("https://example.com/testbot-owner");

    const highlightsPostResponse = await createHighlight(
        client,
        getResponseValue(linksPostResponse, "response.id"),
        "red",
        "Owner private passage",
        "owner note",
        0,
        21
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);

    // The highlight must belong to the SECOND user. If the credentials sign-in did not
    // take effect, this highlight would be owned by the bearer-token user and the 404
    // assertions below would prove nothing about ownership.
    expect(
        String(getResponseValue(highlightsPostResponse, "response.userId")),
        'highlight is owned by the second user, so the identity switch took effect'
    ).toBe(String(getResponseValue(usersPostResponse, "response.id")));
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'owner highlight color').toBe("red");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'owner highlight note').toBe("owner note");

    // Clearing the session cookie reverts the client to the first user's bearer token.
    const signoutPostResponse = await createSignout(client, getResponseValue(csrfGetResponse, "csrfToken"));
    expect(signoutPostResponse.statusCode, 'status code').toBe(302);

    // The first user must not be able to rewrite the second user's highlight.
    const highlightsHighlightsPatchRequestBody: string = `{
        "color": "blue",
        "comment": "tampered by another user"
    }`;
    const highlightsHighlightsPatchResponse = await updateHighlight(
        client,
        getResponseValue(highlightsPostResponse, "response.id"),
        highlightsHighlightsPatchRequestBody,
        404
    );
    expect(highlightsHighlightsPatchResponse.statusCode, 'a foreign highlight must not be updatable').toBe(404);
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response"), 'the refusal names no record belonging to another user').toBe("Highlight not found.");

    // The same route's DELETE already refuses a foreign highlight.
    const highlightsHighlightsDeleteResponse = await deleteHighlight(
        client,
        getResponseValue(highlightsPostResponse, "response.id"),
        404
    );
    expect(highlightsHighlightsDeleteResponse.statusCode, 'a foreign highlight must not be deletable').toBe(404);
    expect(getResponseValue(highlightsHighlightsDeleteResponse, "response"), 'the delete refusal names no record belonging to another user').toBe("Highlight not found.");

    const csrfGet1Response = await getCsrf(client);
    expect(csrfGet1Response.statusCode, 'status code').toBe(200);

    const credentialsPost1Response = await createCredentials(
        client,
        getResponseValue(usersPostResponse, "response.username"),
        ownerPassword,
        getResponseValue(csrfGet1Response, "csrfToken")
    );
    expect(credentialsPost1Response.statusCode, 'status code').toBe(302);

    // Back as the owner: the highlight must be exactly as it was left.
    const highlightsGetResponse = await getHighlightsList(client, {});
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'the owner still has the highlight').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.color"), 'owner highlight colour is unchanged').toBe("red");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.comment"), 'owner highlight note is unchanged').toBe("owner note");

    const linksLinksDeleteResponse = await deleteLink(client, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted the link this test created').toBe(getResponseValue(linksPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(client, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted the collection this test created').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
